CREATE TABLE "dhruv_patient_bio" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" TEXT COLLATE NOCASE NOT NULL, "age" INTEGER NOT NULL, "sex" TEXT COLLATE NOCASE NOT NULL, "phone" INTEGER NOT NULL, "op_number" TEXT COLLATE NOCASE NOT NULL, "doctor_id" INTEGER NOT NULL, "comments" TEXT COLLATE NOCASE NOT NULL, "date_added" TEXT COLLATE NOCASE NOT NULL);

CREATE TABLE "dhruv_procedures" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "date" TEXT COLLATE NOCASE NOT NULL, "patient_op_number" TEXT COLLATE NOCASE NOT NULL, "procedure_done" TEXT COLLATE NOCASE NOT NULL, "misc_details" TEXT COLLATE NOCASE NOT NULL, "next_appointment" TEXT COLLATE NOCASE NOT NULL, "files" TEXT COLLATE NOCASE, "doctor_id" INTEGER NOT NULL);

CREATE TABLE "dhruv_users" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "username" TEXT COLLATE NOCASE NOT NULL, "password" TEXT COLLATE NOCASE NOT NULL, "name" TEXT COLLATE NOCASE NOT NULL, "phone" TEXT COLLATE NOCASE NOT NULL, "regno" TEXT COLLATE NOCASE NOT NULL);

CREATE UNIQUE INDEX "dhruv_patient_bio_op_number" ON "dhruv_patient_bio" ("op_number");

CREATE UNIQUE INDEX "dhruv_users_username" ON "dhruv_users" ("username");
